#!/usr/bin/env python3
"""Private fresh-boot Codex serial experiment; run only under the root controller.

No environment files are written. The first failed stage freezes evidence and
aborts without an automatic stop, recovery, retry, or next launch.
"""
import argparse
import fcntl
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import sys
import time
import urllib.error
import urllib.request

ROOT=Path('/home/t4ce/Repositories/TRUEOS')
CAPTURE=ROOT/'bld/baremetal-logs/trueos-baremetal.2.log'
PXE=ROOT/'tgt/pxe-current'
OUT=Path('/tmp')
LOCK=OUT/'trueos-codex-private-serial-series.lock'
BASE='http://192.168.178.94'
PINS={
 '/tmp/trueos-codex-screen-startup-probe.py':'aec106a048a2cca5b69824eca94dd612011b3d027922a2ef525971027f260e54',
 '/tmp/trueos-codex-analyze-window-v2.py':'27fe662423f35aa24e20bcee0ad2ff83d10aed5c044e73318eeaefef599d67e3',
 '/tmp/trueos-codex-stop-owned.py':'36d56205a558713341d0b421e962e591ab10e38603b0e13d2e636a5105cca4b4',
 '/tmp/trueos-codex-screen-input-probe.py':'855e48b64a329df759ee455f928252ed090cc141c66a7dbb0ef2268ef88654ae',
 '/tmp/trueos-codex-startup-probe.py':'2b26a7bec60f393cfc965a7b4916df18cb9c4d47faae69e4551ef304faf0938d',
 '/tmp/trueos-codex-terminal-observer-dependencies.json':'84e9e68e99e041181dd1164b18dd35cb48db54a1abc96ff0538174f97fa22a29',
 str(ROOT/'tools/codex_retirement_gate.py'):'ede82d7ed3113d7898f3619f3d59d3a5886285de9f4e6e1fd751b107d77d6dca',
 str(ROOT/'tools/codex_startup_report.py'):'73ab5d4187f949c34a85bd89ffa6921bdcd2c8355aefd43a52064157749c7a54',
}

class Abort(Exception):
    pass


def digest(path):
    value=hashlib.sha256()
    with Path(path).open('rb')as stream:
        while chunk:=stream.read(1024*1024):value.update(chunk)
    return value.hexdigest()


def read(path):
    return json.loads(Path(path).read_text())


def trial_name(config,index):
    return f'{config.name}-serial{index}-workers1-two'


def validate_startup(summary,harness,expected_sha256):
    if not harness or harness.get('success')is not True:
        raise Abort('startup_receipt_failed')
    if (harness.get('marker_shape')!='two' or harness.get('draft_echo_observation')!='reconstructed_screen'
            or harness.get('no_input_seconds_after_observed_attach')!=5 or harness.get('turns_submitted')!=0
            or harness.get('clear_barrier',{}).get('marker_absent')is not True):
        raise Abort('startup_protocol_mismatch')
    apps=summary.get('applications',[])
    if len(apps)!=1 or not summary.get('identity_checks') or not all(summary['identity_checks'].values()):
        raise Abort('startup_source_identity_or_policy_failed')
    app=apps[0]
    if app.get('context',{}).get('archive_sha256')!=expected_sha256:
        raise Abort('startup_archive_mismatch')
    if (app.get('runtime')or{}).get('async_workers')!=1:
        raise Abort('startup_runtime_is_not_one_worker')
    if (app.get('startup_websocket_prewarm')!='deferred'
            or app.get('startup_skills_coalescing')is not True
            or app.get('startup_skills_refresh_coalesced')is not True):
        raise Abort('startup_default_policy_mismatch')
    endpoints=app.get('endpoints',{})
    if any(not isinstance(endpoints.get(k),(int,float))for k in ['attach_done_ms','session_ready_frame_ms','startup_handoff_frame_ms']):
        raise Abort('startup_ready_or_handoff_missing')
    if harness.get('ready_without_input')is not True or harness.get('handoff_without_input')is not True:
        raise Abort('startup_ready_not_observed_during_no_input')
    if summary.get('parser_warnings'):
        raise Abort('startup_parser_warnings')
    return app


def validate_retirement(proof,summary):
    app=summary['applications'][0]
    if proof.get('success')is not True or proof.get('observation_kind')!='append_follow':
        raise Abort('retirement_not_complete_live_proof')
    launch=proof.get('launch_proof',{})
    if launch.get('context')!=app['context']:
        raise Abort('retirement_wrong_application_context')
    host=next((r for r in summary['host_requests']if r['request']==app['context']['request']),None)
    entries=[]if host is None else [p for p in host['spans']if p['name']=='guest_entry']
    if len(entries)!=1 or (launch.get('vm'),launch.get('generation'))!=(entries[0]['vm'],entries[0]['gen']):
        raise Abort('retirement_wrong_native_generation')
    fs,offline=proof.get('filesystem_drained')or{},proof.get('offline')or{}
    if any((row.get('vm'),row.get('generation'))!=(launch['vm'],launch['generation'])for row in [fs,offline]):
        raise Abort('retirement_drain_generation_mismatch')
    if (any(fs.get(k)!=0 for k in ['fs_pending','fs_streams','async_fs_pending'])
            or offline.get('native_jobs')!=0 or offline.get('carrier')!='released'
            or not fs.get('offset',-1)<offline.get('offset',-1)):
        raise Abort('retirement_owner_drain_incomplete')


def run_series(config,backend,emit=lambda record:None):
    result={'schema':1,'name':config.name,'success':False,'expected_kernel_sha256':config.kernel_sha256,
            'expected_application_sha256':config.app_sha256,'requested_trials':config.count,
            'no_input_seconds':5,'marker_shape':'two','async_workers':1,'environment_files_written':False,
            'leave_last_running':config.leave_last_running,'trials':[],
            'limits':['Fresh-boot-only series; no resume or automatic retry/recovery.',
                      'Root must serialize manual controls and publication while this host series lock is held.',
                      'Stop acceptance is followed by an exact live retirement gate before any subsequent launch.',
                      'The first failure is left for manual inspection; no automatic stop is attempted after failure.']}
    stage='preflight'
    try:
        result['preflight']=backend.preflight()
        emit({'stage':'preflight','success':True})
        for index in range(1,config.count+1):
            name=trial_name(config,index)
            trial={'index':index,'name':name};result['trials'].append(trial)
            stage='startup'
            emit({'stage':stage,'index':index})
            launched=backend.launch(name);trial['startup_process']=launched['process']
            stage='freeze'
            frozen=backend.freeze(name,launched['capture_start_offset'])
            trial['frozen_summary_path']=frozen['path'];summary=frozen['summary']
            trial['capture']=summary['window']
            # A helper may exit0 while its receipt records failure. Always inspect both.
            if launched['process'].get('returncode')!=0:
                raise Abort('startup_subprocess_failed')
            app=validate_startup(summary,launched.get('harness'),config.app_sha256)
            trial.update(context=app['context'],runtime=app['runtime'],endpoints=app['endpoints'],
                         draft_echo_ms=launched['harness'].get('draft_echo_ms'),
                         clear_ms=launched['harness']['clear_barrier'].get('elapsed_ms'))
            emit({'stage':'startup_verified','index':index,'endpoints':trial['endpoints'],
                  'draft_echo_ms':trial['draft_echo_ms'],'clear_ms':trial['clear_ms']})
            if index==config.count and config.leave_last_running:
                trial['retained_running']=True
                continue
            stage='stop'
            stopped=backend.stop(name);trial['stop_process']=stopped
            if stopped.get('returncode')!=0 or stopped.get('accepted')is not True:
                raise Abort('owned_stop_not_completed_or_accepted')
            stage='retirement'
            retired=backend.retire(name,frozen['path']);trial['retirement']=retired
            if retired['process'].get('returncode')!=0:
                raise Abort('retirement_subprocess_failed')
            validate_retirement(retired['proof'],summary)
            emit({'stage':'retired','index':index,'vm':retired['proof']['launch_proof']['vm'],
                  'generation':retired['proof']['launch_proof']['generation']})
        result['success']=True;result['reason']='requested_series_completed'
    except (Abort,OSError,ValueError,KeyError,TypeError,AttributeError,subprocess.SubprocessError)as error:
        result.update(reason=str(error)if isinstance(error,Abort)else type(error).__name__,incomplete_stage=stage)
        emit({'stage':'aborted','at':stage,'reason':result['reason'],'index':len(result['trials'])})
    return result


class Backend:
    def __init__(self,config):self.config=config

    def check_sources_and_kernel(self):
        for path,expected in PINS.items():
            if digest(path)!=expected:raise Abort('pinned_helper_source_changed')
        publication=read(self.config.kernel_publication)
        if publication.get('kernel_sha256')!=self.config.kernel_sha256:
            raise Abort('kernel_publication_identity_mismatch')
        selected=Path(publication['selected_generation']).resolve()
        if selected!=PXE.resolve()or digest(selected/'TRUEOS.elf')!=self.config.kernel_sha256:
            raise Abort('currently_published_kernel_identity_mismatch')
        return publication

    def http_get(self,path,limit):
        with urllib.request.urlopen(BASE+path,timeout=6)as response:
            body=response.read(limit+1)
            if response.status!=200 or len(body)>limit:raise Abort('bounded_http_read_failed')
        return body

    def preflight(self):
        publication=self.check_sources_and_kernel()
        start=publication['capture_offset_before_reset']
        with CAPTURE.open('rb')as stream:
            st=os.fstat(stream.fileno())
            if not isinstance(start,int)or not 0<=start<st.st_size or st.st_size-start>16*1024*1024:
                raise Abort('fresh_boot_source_window_invalid')
            stream.seek(start);raw=stream.read(st.st_size-start)
        if raw.count(b'Entering TrueOS kernel')!=1:
            raise Abort('one_fresh_boot_after_publication_required')
        if b'\tprocess_context 'in raw:
            raise Abort('fresh_boot_only_existing_codex_context')
        roots=sorted(set(int(x)for x in re.findall(rb'data-root=[\"\x27](\d+)[\"\x27]',self.http_get('/',2*1024*1024))))
        if 2 not in roots:raise Abort('required_data_root2_absent')
        profile=self.http_get('/dl/2/apps/codex/.codex/trueos-threads.conf',128)
        if profile.decode('utf8').split()!=['isolated','2']:
            raise Abort('profile_is_not_isolated2')
        try:
            self.http_get('/dl/2/apps/codex/.codex/.env',65536)
        except urllib.error.HTTPError as error:
            if error.code!=404:raise Abort('dotenv_absence_not_verified')
        else:raise Abort('existing_dotenv_preserved_series_refused')
        self.capture_identity=(st.st_dev,st.st_ino)
        self.capture_offset=st.st_size
        return {'publication_path':str(self.config.kernel_publication),
                'publication_sha256':digest(self.config.kernel_publication),
                'kernel_sha256':self.config.kernel_sha256,'data_root_ids':roots,
                'profile_isolated2':True,'profile_sha256':hashlib.sha256(profile).hexdigest(),'dotenv_status':404,
                'fresh_boot_window':{'start_offset':start,'end_offset':st.st_size,'sha256':hashlib.sha256(raw).hexdigest(),
                                     'file_device':st.st_dev,'file_inode':st.st_ino},'helper_pins':PINS}

    def command(self,args,timeout):
        try:
            completed=subprocess.run(args,check=False,capture_output=True,timeout=timeout)
            stdout,stderr=completed.stdout,completed.stderr
            return {'returncode':completed.returncode,'stdout_bytes':len(stdout),'stderr_bytes':len(stderr)},stdout
        except subprocess.TimeoutExpired as error:
            return {'returncode':None,'error_type':'TimeoutExpired',
                    'stdout_bytes':len(error.stdout or b''),'stderr_bytes':len(error.stderr or b'')},b''

    def check_capture_continuity(self):
        with CAPTURE.open('rb')as stream:
            stat=os.fstat(stream.fileno())
            if(stat.st_dev,stat.st_ino)!=self.capture_identity or stat.st_size<self.capture_offset:
                raise Abort('collector_changed_between_trials')
            if stat.st_size-self.capture_offset>16*1024*1024:
                raise Abort('between_trial_capture_window_limit')
            stream.seek(self.capture_offset);tail=stream.read(stat.st_size-self.capture_offset)
        if b'Entering TrueOS kernel'in tail:raise Abort('new_boot_between_trials')
        if b'\tprocess_context 'in tail:raise Abort('unexpected_application_between_trials')
        return stat.st_size

    def launch(self,name):
        self.check_sources_and_kernel()
        start=self.check_capture_continuity()
        process,_=self.command([sys.executable,'/tmp/trueos-codex-screen-startup-probe.py','--name',name,
            '--expected-sha256',self.config.app_sha256,'--marker-shape','two','--no-input-seconds','5'],180)
        path=OUT/('trueos-codex-'+name+'.json')
        try:
            harness=read(path)if path.exists()else None
            if harness is not None and not isinstance(harness,dict):
                raise ValueError('invalid_receipt_shape')
        except(ValueError,OSError)as error:
            harness=None;process['harness_parse_error_type']=type(error).__name__
        return {'process':process,'harness':harness,'capture_start_offset':start}

    def freeze(self,name,start):
        time.sleep(.3)
        # The frozen analyzer unconditionally opens an existing harness JSON.
        # Preserve unreadable original bytes and select an absent source-only
        # alias rather than feeding a partial file back into that analyzer.
        source_name=name
        harness_path=OUT/('trueos-codex-'+name+'.json')
        if harness_path.exists():
            try:
                if not isinstance(read(harness_path),dict):raise ValueError('invalid_receipt_shape')
            except(ValueError,OSError):source_name=name+'-source-only'
        if source_name!=name and(OUT/('trueos-codex-'+source_name+'.json')).exists():
            raise Abort('source_only_alias_receipt_exists')
        args=[sys.executable,'/tmp/trueos-codex-analyze-window-v2.py','--name',source_name,
              '--expected-sha256',self.config.app_sha256,'--label','series-frozen',
              '--expected-prewarm','deferred','--expected-coalesce','1','--start-offset',str(start)]
        process,_=self.command(args,30)
        path=OUT/('trueos-codex-'+source_name+'-series-frozen-summary.json')
        if process['returncode']!=0 or not path.exists():raise Abort('source_freeze_failed')
        return {'path':str(path),'summary':read(path)}

    def stop(self,name):
        process,stdout=self.command([sys.executable,'/tmp/trueos-codex-stop-owned.py'],45)
        try:payload=json.loads(stdout)
        except(ValueError,UnicodeError):payload={}
        process['accepted']=payload.get('owned_codex_stop')=='accepted'
        path=OUT/('trueos-codex-'+name+'-series-stop.json')
        with path.open('x')as stream:json.dump(process,stream,indent=2);stream.write('\n')
        return process

    def retire(self,name,summary_path):
        path=OUT/('trueos-codex-'+name+'-series-retirement.json')
        process,_=self.command([sys.executable,str(ROOT/'tools/codex_retirement_gate.py'),
            '--startup-summary',summary_path,'--expected-sha256',self.config.app_sha256,
            '--capture',str(CAPTURE),'--output',str(path),'--timeout','60'],75)
        proof=read(path)if path.exists()else{}
        if proof.get('success')is True and proof.get('observation_kind')=='append_follow':
            window=proof['window']
            if(window['file_device'],window['file_inode'])!=self.capture_identity or window['end_offset']<self.capture_offset:
                raise Abort('retirement_capture_continuity_mismatch')
            self.capture_offset=window['end_offset']
        return {'process':process,'path':str(path),'proof':proof}


def main(argv=None):
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--name',required=True)
    parser.add_argument('--count',type=int,default=5)
    parser.add_argument('--expected-sha256',dest='app_sha256',required=True)
    parser.add_argument('--expected-kernel-sha256',dest='kernel_sha256',required=True)
    parser.add_argument('--kernel-publication',type=Path,required=True)
    parser.add_argument('--leave-last-running',action='store_true')
    config=parser.parse_args(argv)
    if not re.fullmatch(r'[a-z0-9][a-z0-9_-]{0,59}',config.name):parser.error('invalid series name')
    if not 1<=config.count<=8:parser.error('count must be1..8')
    if any(not re.fullmatch(r'[0-9a-f]{64}',value)for value in [config.app_sha256,config.kernel_sha256]):parser.error('invalid SHA256')
    output=OUT/('trueos-codex-'+config.name+'-serial-series.json')
    with LOCK.open('a+')as lock:
        try:fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        except BlockingIOError:parser.error('another host serial series is active')
        paths=[output]
        for index in range(1,config.count+1):
            prefix=OUT/('trueos-codex-'+trial_name(config,index))
            paths.extend(Path(str(prefix)+suffix)for suffix in ['.json','-report.json',
                '-series-frozen-summary.json','-series-frozen-report.json','-series-frozen-progress.json',
                '-series-stop.json','-series-retirement.json',
                '-source-only.json','-source-only-report.json',
                '-source-only-series-frozen-summary.json','-source-only-series-frozen-report.json',
                '-source-only-series-frozen-progress.json'])
        if any(path.exists()for path in paths):parser.error('existing series/trial receipt preserved; choose a fresh name')
        result=run_series(config,Backend(config),lambda record:print(json.dumps(record),flush=True))
        result['orchestrator_sha256']=digest(__file__)
        with output.open('x')as stream:json.dump(result,stream,indent=2);stream.write('\n')
        print(json.dumps({'stage':'series_finished','success':result['success'],'reason':result['reason'],'receipt':str(output)}),flush=True)
    return 0 if result['success']else 2

if __name__=='__main__':raise SystemExit(main())
